args.command:
python3 - <<'PY'
import os,re
root='.'
pat=re.compile(r'rate.?limit|rateLimit|throttl|limiter|per.?user|requests?\s*(per|/)|window',re.I)
for dp,_,fs in os.walk(root):
 if any(x in dp for x in ('node_modules','.git')): continue
 for f in fs:
  p=os.path.join(dp,f)
  try:
   with open(p,encoding='utf-8',errors='ignore') as h:
    for n,line in enumerate(h,1):
     if pat.search(line): print(f'{p}:{n}:{line.rstrip()}')
  except (OSError,UnicodeError): pass
PY

